function renderAprioriHomePage() {
  return `<!DOCTYPE html>
  <html lang="es">
    <head>
      <meta charset="UTF-8" />
      <meta name="viewport" content="width=device-width, initial-scale=1.0" />
      <title>Minería de Datos · Modelo Apriori</title>
      <style>
        :root { color-scheme: dark; --bg:#0b0e14; --panel:#131822; --soft:#191f2b; --line:rgba(255,255,255,.09); --text:#f6f1e7; --muted:#9da6b6; --gold:#d5a44f; --gold-soft:rgba(213,164,79,.14); --ok:#5fc49b; --danger:#ef8585; font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif; }
        * { box-sizing:border-box; } .hidden { display:none!important; } body { margin:0; min-height:100vh; color:var(--text); background:radial-gradient(circle at 18% 12%,rgba(213,164,79,.12),transparent 30rem),radial-gradient(circle at 88% 82%,rgba(126,83,171,.15),transparent 34rem),var(--bg); }
        button,input { font:inherit; } button { color:inherit; } .app { min-height:100vh; display:grid; grid-template-columns:250px 1fr; }
        .sidebar { position:sticky; top:0; height:100vh; padding:28px 20px; background:rgba(12,15,22,.92); border-right:1px solid var(--line); backdrop-filter:blur(20px); }
        .brand { padding:6px 8px 28px; border-bottom:1px solid var(--line); } .brand-mark { display:inline-flex; width:42px; height:42px; align-items:center; justify-content:center; border-radius:14px; background:linear-gradient(145deg,var(--gold),#8b5c1e); color:#171108; font-family:Georgia,serif; font-size:1.35rem; font-weight:700; box-shadow:0 12px 30px rgba(213,164,79,.18); }
        .brand h1 { margin:18px 0 5px; font-family:Georgia,serif; font-size:1.45rem; font-weight:500; } .brand p { margin:0; color:var(--muted); font-size:.82rem; }
        .nav { display:grid; gap:9px; margin-top:26px; } .nav-button { display:grid; grid-template-columns:38px 1fr; align-items:center; gap:11px; width:100%; padding:11px; border:1px solid transparent; border-radius:14px; background:transparent; text-align:left; cursor:pointer; }
        .nav-button:hover { background:rgba(255,255,255,.04); } .nav-button.active { border-color:rgba(213,164,79,.24); background:var(--gold-soft); } .nav-icon { display:grid; place-items:center; width:38px; height:38px; border-radius:11px; background:var(--soft); } .nav-button strong { display:block; font-size:.93rem; } .nav-button small { color:var(--muted); }
        .main { min-width:0; padding:34px clamp(20px,4vw,56px) 60px; } .view { display:none; } .view.active { display:block; } .topbar { display:flex; justify-content:space-between; align-items:start; gap:20px; margin-bottom:28px; }
        .eyebrow { color:var(--gold); font-size:.74rem; font-weight:800; letter-spacing:.16em; text-transform:uppercase; } h2 { margin:8px 0 0; font-family:Georgia,serif; font-size:clamp(2rem,4vw,3.4rem); font-weight:500; letter-spacing:-.035em; } .topbar p { max-width:720px; margin:10px 0 0; color:var(--muted); line-height:1.6; }
        .status-pill { flex:0 0 auto; padding:9px 13px; border:1px solid var(--line); border-radius:999px; color:var(--muted); background:var(--panel); font-size:.82rem; } .status-pill.running { color:var(--gold); border-color:rgba(213,164,79,.28); }
        .card { border:1px solid var(--line); border-radius:22px; background:rgba(19,24,34,.86); box-shadow:0 22px 60px rgba(0,0,0,.18); } .form-card { padding:24px; } .section-title { display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:18px; } .section-title h3 { margin:0; font-size:1.05rem; } .section-title span { color:var(--muted); font-size:.82rem; }
        .form-grid { display:grid; grid-template-columns:repeat(4,minmax(150px,1fr)); gap:14px; } label { display:grid; gap:7px; color:#d8dce4; font-size:.82rem; } input { width:100%; padding:11px 12px; border:1px solid var(--line); border-radius:11px; background:#0e121a; color:var(--text); outline:none; } input:focus { border-color:rgba(213,164,79,.65); box-shadow:0 0 0 3px rgba(213,164,79,.09); } .hint { color:var(--muted); font-size:.72rem; }
        .pipeline { display:grid; grid-template-columns:repeat(5,1fr); gap:12px; margin-top:18px; } .stage { min-height:168px; padding:18px; display:flex; flex-direction:column; border:1px solid var(--line); border-radius:18px; background:var(--soft); } .stage-number { color:var(--gold); font-size:.72rem; font-weight:800; letter-spacing:.12em; } .stage h4 { margin:9px 0 6px; } .stage p { margin:0 0 16px; color:var(--muted); font-size:.78rem; line-height:1.45; }
        .run-stage { margin-top:auto; width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:10px; background:rgba(255,255,255,.04); cursor:pointer; } .run-stage:hover { border-color:rgba(213,164,79,.4); background:var(--gold-soft); } .run-stage:disabled,.primary:disabled { opacity:.5; cursor:wait; }
        .actions { display:flex; align-items:center; gap:12px; margin-top:18px; flex-wrap:wrap; } .primary { padding:12px 18px; border:none; border-radius:12px; background:linear-gradient(135deg,#d5a44f,#a87327); color:#151007; font-weight:800; cursor:pointer; } .secondary { padding:11px 16px; border:1px solid var(--line); border-radius:12px; background:transparent; cursor:pointer; } .danger { padding:11px 16px; border:1px solid rgba(239,133,133,.35); border-radius:12px; background:rgba(239,133,133,.08); color:var(--danger); cursor:pointer; } .danger:hover { background:rgba(239,133,133,.15); } .message { color:var(--muted); font-size:.84rem; } .message.ok { color:var(--ok); } .message.error { color:var(--danger); }
        .files-card { margin-top:20px; overflow:hidden; } .files-head { padding:20px 22px; display:flex; justify-content:space-between; align-items:center; gap:12px; border-bottom:1px solid var(--line); } .files-head h3 { margin:0; } .table-wrap { overflow:auto; max-height:440px; } table { width:100%; border-collapse:collapse; font-size:.82rem; } th,td { padding:12px 16px; text-align:left; border-bottom:1px solid var(--line); white-space:nowrap; } th { position:sticky; top:0; background:#151b25; color:var(--muted); font-size:.72rem; letter-spacing:.06em; text-transform:uppercase; } td.path { max-width:700px; color:#d7dbe3; white-space:normal; } .file-name { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .file-config { margin-top:6px; color:var(--gold); font-size:.72rem; line-height:1.45; white-space:normal; } .table-action { border:none; background:transparent; color:var(--gold); cursor:pointer; padding:3px 6px; text-decoration:none; } .empty { padding:34px; color:var(--muted); text-align:center; }
        .history-card { margin-top:20px; padding:22px; } .history-toolbar { display:flex; justify-content:space-between; align-items:end; gap:16px; flex-wrap:wrap; } .history-toolbar label { min-width:min(420px,100%); } .history-actions { display:flex; align-items:center; gap:9px; flex-wrap:wrap; } select { width:100%; padding:11px 12px; border:1px solid var(--line); border-radius:11px; background:#0e121a; color:var(--text); } .summary-grid { display:grid; grid-template-columns:repeat(6,1fr); gap:10px; margin-top:18px; } .summary-item { padding:14px; border:1px solid var(--line); border-radius:14px; background:var(--soft); } .summary-item strong { display:block; font-size:1.35rem; color:var(--gold); } .summary-item span { display:block; margin-top:4px; color:var(--muted); font-size:.72rem; } .zip-link,.activate-run { display:inline-flex; padding:11px 15px; border:1px solid transparent; border-radius:11px; background:var(--gold-soft); color:var(--gold); text-decoration:none; font-size:.84rem; cursor:pointer; } .activate-run { border-color:rgba(213,164,79,.25); } .activate-run.active { color:var(--ok); border-color:rgba(95,196,155,.3); background:rgba(95,196,155,.1); cursor:default; } .zip-link.hidden { display:none; } .comparison { margin-top:22px; } .comparison h3 { margin:0 0 5px; } .comparison > p { margin:0 0 14px; color:var(--muted); font-size:.8rem; } .comparison-table { border:1px solid var(--line); border-radius:14px; overflow:auto; } .comparison-table tr.selected-support td { background:var(--gold-soft); } .choose-support { padding:7px 10px; border:1px solid rgba(213,164,79,.34); border-radius:9px; background:transparent; color:var(--gold); cursor:pointer; } .choose-support:disabled { opacity:.55; cursor:default; }
        .orders-card { overflow:hidden; } .orders-toolbar { display:flex; justify-content:space-between; align-items:end; gap:16px; padding:18px 20px; border-bottom:1px solid var(--line); flex-wrap:wrap; } .orders-toolbar label:first-child { width:110px; } .orders-toolbar label:last-child { width:min(340px,100%); } .orders-table-wrap { overflow:auto; min-height:300px; max-height:58vh; } .orders-table td { vertical-align:middle; } .client-name { color:#e4d5b8; font-weight:650; } .eye-button { display:grid; place-items:center; width:36px; height:36px; border:1px solid rgba(213,164,79,.35); border-radius:11px; background:var(--gold-soft); color:var(--gold); cursor:pointer; } .eye-button:hover { background:rgba(213,164,79,.24); } .eye-button svg { width:18px; height:18px; fill:none; stroke:currentColor; stroke-width:1.8; } .pagination { display:flex; justify-content:space-between; align-items:center; gap:12px; padding:15px 20px; color:var(--muted); font-size:.8rem; border-top:1px solid var(--line); } .page-actions { display:flex; gap:8px; } .page-button { padding:7px 11px; border:1px solid var(--line); border-radius:9px; background:transparent; cursor:pointer; } .page-button:disabled { opacity:.4; cursor:default; } .item-summary { display:flex; gap:18px; flex-wrap:wrap; color:var(--muted); font-size:.8rem; } .item-summary strong { color:var(--text); } .order-detail-table td:nth-child(3),.order-detail-table td:nth-child(4){text-align:right;}
        .modal-actions { display:flex; align-items:center; gap:9px; } .recommend-button { padding:9px 14px; border:0; border-radius:10px; background:linear-gradient(135deg,#d5a44f,#a87327); color:#151007; font-weight:800; cursor:pointer; } .recommendations { padding:20px; border-top:1px solid var(--line); background:rgba(213,164,79,.035); } .recommendations h4 { margin:0 0 6px; } .recommendation-note { margin:0 0 14px; color:var(--muted); font-size:.78rem; } .category-chips { display:flex; flex-wrap:wrap; gap:7px; margin:10px 0 16px; } .category-chip { padding:6px 9px; border-radius:999px; background:rgba(255,255,255,.05); color:#ccd2dc; font-size:.72rem; } .recommendation-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; } .recommendation-card { padding:15px; border:1px solid var(--line); border-radius:15px; background:var(--panel); } .category-button { width:100%; padding:0; border:0; background:transparent; color:var(--gold); text-align:left; font-weight:800; cursor:pointer; } .rule-metrics { display:flex; gap:10px; margin:8px 0; color:var(--muted); font-size:.72rem; flex-wrap:wrap; } .rule-details { margin-top:9px; color:var(--muted); font-size:.72rem; } .rule-details summary { color:#d7dbe3; cursor:pointer; } .rule-row { padding:8px 0; border-top:1px solid var(--line); white-space:normal; line-height:1.45; } .products-panel { margin-top:18px; border:1px solid var(--line); border-radius:15px; overflow:hidden; } .products-head { padding:14px 16px; background:var(--soft); } .products-head h4 { margin:0; } .stock-ok { color:var(--ok); font-weight:750; } .product-photo-cell { width:92px; text-align:center; } .product-image-button { width:64px; height:64px; padding:4px; border:1px solid var(--line); border-radius:11px; background:#f7f7f5; cursor:pointer; overflow:hidden; } .product-image-button:hover,.product-image-button:focus-visible { border-color:var(--gold); box-shadow:0 0 0 3px rgba(213,164,79,.12); outline:none; } .product-thumbnail { display:block; width:100%; height:100%; object-fit:contain; border-radius:7px; } .no-photo { display:inline-flex; width:64px; height:64px; align-items:center; justify-content:center; border:1px solid var(--line); border-radius:11px; color:var(--muted); background:var(--soft); font-size:.68rem; } .image-modal { z-index:30; } .image-modal-card { width:min(1050px,100%); } .image-tools { display:flex; align-items:center; gap:8px; } .zoom-button { min-width:36px; height:34px; border:1px solid var(--line); border-radius:9px; background:var(--soft); cursor:pointer; } .zoom-label { min-width:58px; color:var(--muted); text-align:center; font-size:.8rem; } .image-stage { display:grid; place-items:center; min-height:420px; max-height:76vh; padding:24px; overflow:auto; background:#090d15; } .product-image-large { display:block; max-width:min(760px,90%); max-height:68vh; object-fit:contain; transform-origin:center; transition:transform .15s ease; } @media(max-width:800px){.recommendation-grid{grid-template-columns:1fr}.image-stage{min-height:300px;padding:14px}}
        .modal { position:fixed; inset:0; z-index:10; display:none; padding:28px; background:rgba(3,5,8,.74); backdrop-filter:blur(7px); } .modal.open { display:grid; place-items:center; } .modal-card { width:min(1180px,100%); max-height:88vh; overflow:hidden; border:1px solid var(--line); border-radius:20px; background:#111620; box-shadow:0 30px 90px rgba(0,0,0,.48); } .modal-head { padding:17px 20px; display:flex; justify-content:space-between; gap:16px; border-bottom:1px solid var(--line); } .modal-head h3 { margin:0; font-size:.95rem; } .modal-close { border:none; background:transparent; color:var(--muted); cursor:pointer; } .preview-wrap { max-height:68vh; overflow:auto; } .preview-meta { padding:10px 18px; color:var(--muted); font-size:.78rem; border-top:1px solid var(--line); }
        @media(max-width:1100px){.form-grid{grid-template-columns:repeat(2,1fr)}.pipeline{grid-template-columns:repeat(2,1fr)}.summary-grid{grid-template-columns:repeat(3,1fr)}} @media(max-width:760px){.app{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav{grid-template-columns:1fr 1fr}.main{padding:24px 16px 48px}.form-grid,.pipeline,.summary-grid{grid-template-columns:1fr}.topbar{flex-direction:column}}
      </style>
    </head>
    <body>
      <div class="app">
        <aside class="sidebar"><div class="brand"><span class="brand-mark">A</span><h1>Modelo Apriori</h1><p>Minería de datos · Viamore</p></div><nav class="nav" aria-label="Navegación principal"><button class="nav-button active" data-view="settings-view" type="button"><span class="nav-icon">⚙</span><span><strong>Ajustes</strong><small>Procesamiento y reglas</small></span></button><button class="nav-button" data-view="orders-view" type="button"><span class="nav-icon">◇</span><span><strong>Pedidos</strong><small>Recomendaciones</small></span></button></nav></aside>
        <main class="main">
          <section id="settings-view" class="view active">
            <header class="topbar"><div><span class="eyebrow">Panel de análisis</span><h2>Ajustes del modelo</h2><p>Configurá y ejecutá cada etapa del proceso. Los resultados se guardan como CSV auditables y pueden revisarse desde este panel.</p></div><span id="process-status" class="status-pill">Sistema disponible</span></header>
            <section class="card form-card">
              <div class="section-title"><h3>Parámetros de la corrida</h3><span>Los porcentajes se ingresan como números enteros</span></div>
              <form id="settings-form"><div class="form-grid">
                <label>Últimas facturas<input name="invoiceLimit" type="number" min="1" value="1500" required /><span class="hint">Cantidad de facturas distintas.</span></label><label>Versión de catálogo<input name="catalogRunId" type="number" min="1" value="970" required /><span class="hint">id_provecomerce.</span></label><label>Soportes a probar (%)<input name="supports" value="1,2,3,4,5" required /><span class="hint">Separados por coma.</span></label><label>Confianza reglas (%)<input name="ruleConfidence" type="number" min="0" max="100" step="1" value="30" required /><span class="hint">Filtro al generar reglas.</span></label>
                <label>Lift mínimo reglas<input name="ruleLift" type="number" min="0" step="0.01" value="1" required /><span class="hint">Se conserva lift estrictamente mayor.</span></label><label>Soporte para seleccionar (%)<input name="selectionSupport" type="number" min="1" value="3" required /><span class="hint">Debe estar en los soportes probados.</span></label><label>Confianza selección (%)<input name="selectionConfidence" type="number" min="0" max="100" step="1" value="40" required /><span class="hint">Filtro para candidatas finales.</span></label><label>Lift selección<input name="selectionLift" type="number" min="0" step="0.01" value="1.2" required /><span class="hint">Filtro para candidatas finales.</span></label>
                <label>Máximo de reglas<input name="maxRules" type="number" min="1" value="20" required /><span class="hint">Límite total de selección.</span></label><label>Máximo por consecuente<input name="maxPerConsequent" type="number" min="1" value="2" required /><span class="hint">Favorece diversidad.</span></label>
              </div></form>
              <div class="pipeline"><article class="stage"><span class="stage-number">01 · EXTRACCIÓN</span><h4>Facturas y categorías</h4><p>Crea una corrida nueva y ejecuta el proceso completo con datos actuales de MySQL.</p><button class="run-stage" data-step="extract" type="button">Crear nueva corrida</button></article><article class="stage"><span class="stage-number">02 · MATRIZ</span><h4>Matriz binaria</h4><p>Reutiliza la extracción seleccionada y recalcula las etapas 02 a 05.</p><button class="run-stage" data-step="matrix" type="button">Reprocesar desde matriz</button></article><article class="stage"><span class="stage-number">03 · APRIORI</span><h4>Itemsets frecuentes</h4><p>Reutiliza la matriz seleccionada y recalcula las etapas 03 a 05.</p><button class="run-stage" data-step="itemsets" type="button">Reprocesar desde Apriori</button></article><article class="stage"><span class="stage-number">04 · REGLAS</span><h4>Confianza y lift</h4><p>Reutiliza los itemsets seleccionados y recalcula las etapas 04 y 05.</p><button class="run-stage" data-step="rules" type="button">Reprocesar desde reglas</button></article><article class="stage"><span class="stage-number">05 · SELECCIÓN</span><h4>Reglas candidatas</h4><p>Reutiliza las reglas de la corrida seleccionada y aplica los filtros finales.</p><button class="run-stage" data-step="select" type="button">Actualizar selección</button></article></div>
              <div class="actions"><button id="run-all" class="primary" type="button">Ejecutar proceso completo</button><button id="refresh-files" class="secondary" type="button">Actualizar archivos</button><button id="reset-settings" class="danger" type="button">Restablecer configuración</button><span id="run-message" class="message">Cargando configuración…</span></div>
            </section>
            <section class="card history-card"><div class="history-toolbar"><label>Corrida histórica<select id="run-select"><option value="">Cargando corridas…</option></select><span class="hint">Las ejecuciones completas se conservan con fecha y hora.</span></label><div class="history-actions"><button id="activate-run" class="activate-run" type="button">Activar para Pedidos</button><a id="zip-link" class="zip-link hidden" href="#">Descargar auditoría ZIP</a><button id="delete-runs" class="danger" type="button">Eliminar todas las ejecuciones</button></div></div><div id="run-summary" class="summary-grid"><div class="summary-item"><strong>—</strong><span>Sin corrida seleccionada</span></div></div><div class="comparison"><h3>Comparación de soportes</h3><p>Compará todos los umbrales con los mismos criterios de confianza y lift antes de elegir las reglas finales.</p><div class="comparison-table"><table><thead><tr><th>Soporte</th><th>Mín. facturas</th><th>Itemsets</th><th>Reglas</th><th>Elegibles</th><th>Consecuentes</th><th>Conf. mediana</th><th>Lift mediano</th><th>Reglas fuertes</th><th>Acción</th></tr></thead><tbody id="comparison-body"><tr><td colspan="10" class="empty">Seleccioná una corrida.</td></tr></tbody></table></div></div></section>
            <section class="card files-card"><div class="files-head"><div><h3>Archivos de la corrida</h3><span class="hint">Vista previa de las primeras 50 filas</span></div><span id="file-count" class="hint">Cargando…</span></div><div class="table-wrap"><table><thead><tr><th>Archivo</th><th>Tamaño</th><th>Actualizado</th><th>Acciones</th></tr></thead><tbody id="files-body"></tbody></table></div></section>
          </section>
          <section id="orders-view" class="view"><header class="topbar"><div><span class="eyebrow">Operación comercial</span><h2>Pedidos web</h2><p>Pedidos vinculados a una orden web. Consultá los artículos de cada pedido sin modificar la información comercial.</p></div><span id="orders-status" class="status-pill">Solo lectura</span></header><section class="card orders-card"><div class="orders-toolbar"><label>Mostrar<select id="orders-page-size"><option>10</option><option>25</option><option>50</option><option>100</option></select></label><label>Buscar<input id="orders-search" type="search" placeholder="Pedido, cliente, vendedora u orden web" /></label></div><div class="orders-table-wrap"><table class="orders-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Vendedora</th><th>OrdenWeb</th><th>Acción</th></tr></thead><tbody id="orders-body"><tr><td colspan="6" class="empty">Abrí la sección para cargar los pedidos.</td></tr></tbody></table></div><div class="pagination"><span id="orders-page-info">—</span><div class="page-actions"><button id="orders-prev" class="page-button" type="button">Anterior</button><button id="orders-next" class="page-button" type="button">Siguiente</button></div></div></section></section>
        </main>
      </div>
      <div id="preview-modal" class="modal" aria-hidden="true"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="preview-title"><div class="modal-head"><h3 id="preview-title">Vista previa</h3><button id="preview-close" class="modal-close" type="button">Cerrar</button></div><div class="preview-wrap"><table><thead id="preview-head"></thead><tbody id="preview-body"></tbody></table></div><div id="preview-meta" class="preview-meta"></div></div></div>
      <div id="order-modal" class="modal" aria-hidden="true"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="order-modal-title"><div class="modal-head"><div><h3 id="order-modal-title">Artículos del pedido</h3><div id="order-modal-summary" class="item-summary"></div></div><div class="modal-actions"><button id="order-recommend" class="recommend-button" type="button">Recomendar</button><button id="order-modal-close" class="modal-close" type="button">Cerrar</button></div></div><div class="preview-wrap"><table class="order-detail-table"><thead><tr><th>Artículo</th><th>Detalle</th><th>Cantidad</th><th>Precio</th></tr></thead><tbody id="order-items-body"></tbody></table><section id="recommendations-panel" class="recommendations hidden"><h4>Recomendaciones Apriori</h4><p id="recommendation-note" class="recommendation-note"></p><div id="present-categories" class="category-chips"></div><div id="recommendations-body" class="recommendation-grid"></div><div id="products-panel" class="products-panel hidden"><div class="products-head"><h4 id="products-title">Artículos disponibles</h4><span class="hint">Stock interno mayor a 10</span></div><div class="table-wrap"><table><thead><tr><th>Artículo</th><th>Descripción</th><th>Stock</th><th>Foto</th></tr></thead><tbody id="products-body"></tbody></table></div></div></section></div><div id="order-items-meta" class="preview-meta"></div></div></div>
      <div id="image-modal" class="modal image-modal" aria-hidden="true"><div class="modal-card image-modal-card" role="dialog" aria-modal="true" aria-labelledby="image-modal-title"><div class="modal-head"><h3 id="image-modal-title">Imagen del artículo</h3><div class="image-tools"><button id="image-zoom-in" class="zoom-button" type="button" aria-label="Ampliar imagen">+</button><button id="image-zoom-out" class="zoom-button" type="button" aria-label="Reducir imagen">−</button><span id="image-zoom-label" class="zoom-label">100%</span><button id="image-modal-close" class="modal-close" type="button">Cerrar</button></div></div><div class="image-stage"><img id="product-image-large" class="product-image-large" alt="" /></div></div></div>
      <script>
        const navButtons=[...document.querySelectorAll('.nav-button')],views=[...document.querySelectorAll('.view')],form=document.getElementById('settings-form'),message=document.getElementById('run-message'),processStatus=document.getElementById('process-status'),stageButtons=[...document.querySelectorAll('.run-stage')],runAllButton=document.getElementById('run-all'),resetSettingsButton=document.getElementById('reset-settings'),deleteRunsButton=document.getElementById('delete-runs'),filesBody=document.getElementById('files-body'),fileCount=document.getElementById('file-count'),runSelect=document.getElementById('run-select'),runSummary=document.getElementById('run-summary'),comparisonBody=document.getElementById('comparison-body'),activateRunButton=document.getElementById('activate-run'),zipLink=document.getElementById('zip-link'),modal=document.getElementById('preview-modal'),previewTitle=document.getElementById('preview-title'),previewHead=document.getElementById('preview-head'),previewBody=document.getElementById('preview-body'),previewMeta=document.getElementById('preview-meta');
        let displayedRunSettings=null,activeRunId=null;
        const ordersBody=document.getElementById('orders-body'),ordersPageInfo=document.getElementById('orders-page-info'),ordersPrev=document.getElementById('orders-prev'),ordersNext=document.getElementById('orders-next'),ordersPageSize=document.getElementById('orders-page-size'),ordersSearch=document.getElementById('orders-search'),ordersStatus=document.getElementById('orders-status'),orderModal=document.getElementById('order-modal'),orderModalTitle=document.getElementById('order-modal-title'),orderModalSummary=document.getElementById('order-modal-summary'),orderItemsBody=document.getElementById('order-items-body'),orderItemsMeta=document.getElementById('order-items-meta'),orderRecommend=document.getElementById('order-recommend'),recommendationsPanel=document.getElementById('recommendations-panel'),recommendationNote=document.getElementById('recommendation-note'),presentCategories=document.getElementById('present-categories'),recommendationsBody=document.getElementById('recommendations-body'),productsPanel=document.getElementById('products-panel'),productsTitle=document.getElementById('products-title'),productsBody=document.getElementById('products-body'),imageModal=document.getElementById('image-modal'),imageModalTitle=document.getElementById('image-modal-title'),productImageLarge=document.getElementById('product-image-large'),imageZoomLabel=document.getElementById('image-zoom-label');
        let ordersState={page:1,pageSize:10,total:0,totalPages:1,search:''},ordersLoaded=false,searchTimer=null,settingsSaveTimer=null,currentOrderId=null,imageZoom=1;
        const escapeHtml=(value)=>String(value??'').replace(/[&<>'"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char])),formatBytes=(bytes)=>bytes<1024?bytes+' B':bytes<1048576?(bytes/1024).toFixed(1)+' KB':(bytes/1048576).toFixed(1)+' MB',formatDate=(value)=>new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)),formatOrderDate=(value)=>value?new Intl.DateTimeFormat('es-AR',{dateStyle:'medium'}).format(new Date(value)):'Sin fecha',formatMoney=(value)=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS'}).format(Number(value)||0),formatPercent=(value)=>value==null?'—':new Intl.NumberFormat('es-AR',{style:'percent',minimumFractionDigits:1,maximumFractionDigits:1}).format(value),safeImageUrl=(value)=>{try{const url=new URL(String(value||''),window.location.origin);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return'';}};
        navButtons.forEach((button)=>button.addEventListener('click',()=>{navButtons.forEach((item)=>item.classList.toggle('active',item===button));views.forEach((view)=>view.classList.toggle('active',view.id===button.dataset.view));if(button.dataset.view==='orders-view'&&!ordersLoaded){ordersLoaded=true;loadOrders();}}));

        async function loadOrders(){ordersStatus.textContent='Cargando…';ordersStatus.classList.add('running');ordersBody.innerHTML='<tr><td colspan="6" class="empty">Consultando pedidos web…</td></tr>';try{const params=new URLSearchParams({page:ordersState.page,pageSize:ordersState.pageSize,search:ordersState.search});const response=await fetch('/api/apriori/orders?'+params);const body=await response.json();if(!response.ok)throw new Error(body.error);ordersState={...ordersState,...body.pagination};ordersBody.innerHTML=body.orders.length?body.orders.map((order)=>\`<tr><td><strong>\${escapeHtml(order.pedido??'—')}</strong></td><td class="client-name">\${escapeHtml(order.cliente)}</td><td>\${formatOrderDate(order.fecha)}</td><td>\${escapeHtml(order.vendedora)}</td><td>\${escapeHtml(order.ordenWeb)}</td><td><button class="eye-button view-order" data-id="\${order.id}" aria-label="Ver artículos del pedido \${escapeHtml(order.pedido)}" title="Ver artículos"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></td></tr>\`).join(''):'<tr><td colspan="6" class="empty">No se encontraron pedidos web.</td></tr>';const first=ordersState.total?((ordersState.page-1)*ordersState.pageSize)+1:0,last=Math.min(ordersState.page*ordersState.pageSize,ordersState.total);ordersPageInfo.textContent='Mostrando '+first+'–'+last+' de '+ordersState.total+' pedidos';ordersPrev.disabled=ordersState.page<=1;ordersNext.disabled=ordersState.page>=ordersState.totalPages;document.querySelectorAll('.view-order').forEach((button)=>button.addEventListener('click',()=>openOrderDetail(button.dataset.id)));ordersStatus.textContent=ordersState.total+' pedidos web';}catch(error){ordersBody.innerHTML='<tr><td colspan="6" class="empty">'+escapeHtml(error.message)+'</td></tr>';ordersPageInfo.textContent='No se pudieron cargar los pedidos';ordersStatus.textContent='Error';}finally{ordersStatus.classList.remove('running');}}
        async function openOrderDetail(orderId){currentOrderId=orderId;orderRecommend.disabled=false;recommendationsPanel.classList.add('hidden');productsPanel.classList.add('hidden');orderModal.classList.add('open');orderModal.setAttribute('aria-hidden','false');orderModalTitle.textContent='Artículos del pedido';orderModalSummary.innerHTML='';orderItemsBody.innerHTML='<tr><td colspan="4" class="empty">Cargando artículos…</td></tr>';orderItemsMeta.textContent='';try{const response=await fetch('/api/apriori/orders/'+encodeURIComponent(orderId)+'/items');const body=await response.json();if(!response.ok)throw new Error(body.error);orderModalTitle.textContent='Pedido '+(body.order.pedido??'—');orderModalSummary.innerHTML='<span>Cliente: <strong>'+escapeHtml(body.order.cliente)+'</strong></span><span>Orden web: <strong>'+escapeHtml(body.order.ordenWeb)+'</strong></span>';orderItemsBody.innerHTML=body.items.length?body.items.map((item)=>\`<tr><td><strong>\${escapeHtml(item.articulo??'—')}</strong></td><td>\${escapeHtml(item.detalle??'Sin detalle')}</td><td>\${escapeHtml(item.cantidad??0)}</td><td>\${formatMoney(item.precio)}</td></tr>\`).join(''):'<tr><td colspan="4" class="empty">El pedido no tiene artículos registrados.</td></tr>';orderItemsMeta.textContent=body.items.length+' artículos registrados.';}catch(error){orderRecommend.disabled=true;orderItemsBody.innerHTML='<tr><td colspan="4" class="empty">'+escapeHtml(error.message)+'</td></tr>';}}
        async function loadRecommendations(){if(!currentOrderId)return;recommendationsPanel.classList.remove('hidden');productsPanel.classList.add('hidden');recommendationNote.textContent='Evaluando las categorías del pedido contra las reglas activas…';presentCategories.innerHTML='';recommendationsBody.innerHTML='<div class="empty">Calculando recomendaciones…</div>';orderRecommend.disabled=true;try{const response=await fetch('/api/apriori/orders/'+encodeURIComponent(currentOrderId)+'/recommendations');const body=await response.json();if(!response.ok)throw new Error(body.error);recommendationNote.textContent='Corrida '+body.activeRun.id+' · soporte '+body.activeRun.support+'% · '+body.unmappedItems+' artículos sin categoría.';presentCategories.innerHTML=body.presentCategories.map((category)=>'<span class="category-chip">'+escapeHtml(category)+'</span>').join('');recommendationsBody.innerHTML=body.recommendations.length?body.recommendations.map((item)=>\`<article class="recommendation-card"><button class="category-button recommended-category" data-category="\${escapeHtml(item.category)}">\${escapeHtml(item.category)}</button><div class="rule-metrics"><span>Confianza \${formatPercent(item.bestRule.confidence)}</span><span>Lift \${Number(item.bestRule.lift).toFixed(2)}</span><span>\${item.rules.length} regla(s)</span></div><details class="rule-details"><summary>Ver reglas que la respaldan</summary>\${item.rules.map((rule)=>\`<div class="rule-row"><strong>\${escapeHtml(rule.antecedent.join(' + '))}</strong> → \${escapeHtml(rule.consequent)}<br>Soporte \${formatPercent(rule.support)} · Confianza \${formatPercent(rule.confidence)} · Lift \${Number(rule.lift).toFixed(2)}</div>\`).join('')}</details></article>\`).join(''):'<div class="empty">No existen reglas aplicables para las categorías actuales del pedido.</div>';document.querySelectorAll('.recommended-category').forEach((button)=>button.addEventListener('click',()=>loadRecommendationProducts(button.dataset.category)));}catch(error){recommendationNote.textContent='';recommendationsBody.innerHTML='<div class="empty">'+escapeHtml(error.message)+'</div>';}finally{orderRecommend.disabled=false;}}
        async function loadRecommendationProducts(category){productsPanel.classList.remove('hidden');productsTitle.textContent='Artículos disponibles · '+category;productsBody.innerHTML='<tr><td colspan="4" class="empty">Consultando stock interno…</td></tr>';try{const response=await fetch('/api/apriori/orders/'+encodeURIComponent(currentOrderId)+'/recommendations/products?category='+encodeURIComponent(category));const body=await response.json();if(!response.ok)throw new Error(body.error);productsBody.innerHTML=body.products.length?body.products.map((product)=>{const photo=safeImageUrl(product.foto_url);const description=product.nombreWeb||product.detalle||'Sin descripción';return \`<tr><td><strong>\${escapeHtml(product.articulo)}</strong></td><td>\${escapeHtml(description)}</td><td class="stock-ok">\${escapeHtml(product.stock)}</td><td class="product-photo-cell">\${photo?\`<button class="product-image-button" type="button" data-src="\${escapeHtml(photo)}" data-title="\${escapeHtml(description)}" aria-label="Ampliar foto de \${escapeHtml(description)}"><img class="product-thumbnail" src="\${escapeHtml(photo)}" alt="" loading="lazy" /></button>\`:'<span class="no-photo">Sin foto</span>'}</td></tr>\`;}).join(''):'<tr><td colspan="4" class="empty">No hay artículos de esta categoría con stock mayor a 10.</td></tr>';document.querySelectorAll('.product-image-button').forEach((button)=>button.addEventListener('click',()=>openProductImage(button.dataset.src,button.dataset.title)));document.querySelectorAll('.product-thumbnail').forEach((image)=>image.addEventListener('error',()=>{const button=image.closest('.product-image-button');if(button)button.outerHTML='<span class="no-photo">Sin foto</span>';}));}catch(error){productsBody.innerHTML='<tr><td colspan="4" class="empty">'+escapeHtml(error.message)+'</td></tr>';}}
        function setImageZoom(value){imageZoom=Math.min(2.5,Math.max(.5,value));productImageLarge.style.transform='scale('+imageZoom+')';imageZoomLabel.textContent=Math.round(imageZoom*100)+'%';}
        function openProductImage(src,title){const safeSrc=safeImageUrl(src);if(!safeSrc)return;imageModalTitle.textContent=title||'Imagen del artículo';productImageLarge.src=safeSrc;productImageLarge.alt=title||'Imagen del artículo';setImageZoom(1);imageModal.classList.add('open');imageModal.setAttribute('aria-hidden','false');}
        function closeProductImage(){imageModal.classList.remove('open');imageModal.setAttribute('aria-hidden','true');productImageLarge.removeAttribute('src');productImageLarge.alt='';setImageZoom(1);}
        function closeOrderModal(){currentOrderId=null;orderModal.classList.remove('open');orderModal.setAttribute('aria-hidden','true');}
        orderRecommend.addEventListener('click',loadRecommendations);
        document.getElementById('order-modal-close').addEventListener('click',closeOrderModal);orderModal.addEventListener('click',(event)=>{if(event.target===orderModal)closeOrderModal();});document.getElementById('image-modal-close').addEventListener('click',closeProductImage);document.getElementById('image-zoom-in').addEventListener('click',()=>setImageZoom(imageZoom+.25));document.getElementById('image-zoom-out').addEventListener('click',()=>setImageZoom(imageZoom-.25));imageModal.addEventListener('click',(event)=>{if(event.target===imageModal)closeProductImage();});ordersPrev.addEventListener('click',()=>{if(ordersState.page>1){ordersState.page-=1;loadOrders();}});ordersNext.addEventListener('click',()=>{if(ordersState.page<ordersState.totalPages){ordersState.page+=1;loadOrders();}});ordersPageSize.addEventListener('change',()=>{ordersState.page=1;ordersState.pageSize=Number(ordersPageSize.value);loadOrders();});ordersSearch.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{ordersState.page=1;ordersState.search=ordersSearch.value.trim();loadOrders();},350);});
        function settings(){const values=Object.fromEntries(new FormData(form).entries());return {...values,supports:values.supports.split(',').map((value)=>value.trim()).filter(Boolean)};}
        function populateSettings(values){Object.entries(values||{}).forEach(([name,value])=>{const input=form.elements.namedItem(name);if(input)input.value=Array.isArray(value)?value.join(','):value;});}
        async function loadSettings(){try{const response=await fetch('/api/apriori/settings');const body=await response.json();if(!response.ok)throw new Error(body.error);populateSettings(body.settings);message.className='message ok';message.textContent=body.persisted?'Configuración guardada cargada.':'Valores predeterminados cargados.';}catch(error){message.className='message error';message.textContent=error.message;}}
        async function saveCurrentSettings(){try{const response=await fetch('/api/apriori/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({settings:settings()})});const body=await response.json();if(!response.ok)throw new Error(body.error);message.className='message ok';message.textContent='Configuración guardada automáticamente.';}catch(error){message.className='message error';message.textContent=error.message;}}
        form.addEventListener('input',()=>{clearTimeout(settingsSaveTimer);message.className='message';message.textContent='Guardando configuración…';settingsSaveTimer=setTimeout(saveCurrentSettings,500);});
        resetSettingsButton.addEventListener('click',async()=>{if(!window.confirm('¿Restablecer todos los parámetros a sus valores predeterminados? Las corridas y reglas generadas no se eliminarán.'))return;clearTimeout(settingsSaveTimer);resetSettingsButton.disabled=true;try{const response=await fetch('/api/apriori/settings',{method:'DELETE'});const body=await response.json();if(!response.ok)throw new Error(body.error);populateSettings(body.settings);message.className='message ok';message.textContent='Configuración restablecida a los valores predeterminados.';}catch(error){message.className='message error';message.textContent=error.message;}finally{resetSettingsButton.disabled=false;}});
        function setRunning(running,label){stageButtons.forEach((button)=>{button.disabled=running;});runAllButton.disabled=running;deleteRunsButton.disabled=running;processStatus.classList.toggle('running',running);processStatus.textContent=running?label:'Sistema disponible';}
        async function reprocess(runId,step){setRunning(true,'Reprocesando corrida…');message.className='message';message.textContent='Reprocesando desde la etapa '+step+' y actualizando sus dependencias…';try{const response=await fetch('/api/apriori/reprocess',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId,step,settings:settings()})});const body=await response.json();if(!response.ok)throw new Error(body.error||'No se pudo reprocesar la corrida.');message.className='message ok';message.textContent='Corrida reprocesada desde '+step+'. Se actualizaron todas las etapas posteriores.';await loadRuns(runId);}catch(error){message.className='message error';message.textContent=error.message;}finally{setRunning(false);}}
        async function execute(step){if(step==='extract')step='all';if(step==='select'){const runId=runSelect.value;if(!runId){message.className='message error';message.textContent='Seleccioná una corrida histórica antes de actualizar la selección.';return;}return chooseSupport(runId,Number(settings().selectionSupport));}if(step!=='all'){const runId=runSelect.value;if(!runId){message.className='message error';message.textContent='Seleccioná una corrida histórica antes de reprocesar una etapa.';return;}return reprocess(runId,step);}setRunning(true,'Procesando…');message.className='message';message.textContent='Ejecutando y guardando una nueva corrida…';try{const response=await fetch('/api/apriori/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({step,settings:settings()})});const body=await response.json();if(!response.ok)throw new Error(body.error||'No se pudo ejecutar el procesamiento.');const summary=body.results.map((result)=>result.output.split(/\\r?\\n/)[0]).join(' · ');message.className='message ok';message.textContent='Proceso completado. '+summary;await loadRuns(body.runId);}catch(error){message.className='message error';message.textContent=error.message;}finally{setRunning(false);}}
        stageButtons.forEach((button)=>button.addEventListener('click',()=>execute(button.dataset.step)));runAllButton.addEventListener('click',()=>execute('all'));document.getElementById('refresh-files').addEventListener('click',()=>loadFiles(runSelect.value));
        async function loadRuns(preferredRun){try{const response=await fetch('/api/apriori/runs');const body=await response.json();if(!response.ok)throw new Error(body.error);activeRunId=body.runs.find((run)=>run.active)?.id||null;if(!body.runs.length){runSelect.innerHTML='<option value="">Sin corridas históricas</option>';runSummary.innerHTML='<div class="summary-item"><strong>—</strong><span>Ejecutá el proceso completo</span></div>';comparisonBody.innerHTML='<tr><td colspan="10" class="empty">No hay corridas para comparar.</td></tr>';activateRunButton.disabled=true;zipLink.classList.add('hidden');await loadFiles();return;}const selected=preferredRun||runSelect.value||body.runs[0].id;runSelect.innerHTML=body.runs.map((run)=>\`<option value="\${escapeHtml(run.id)}" \${run.id===selected?'selected':''}>\${formatDate(run.startedAt)} · \${escapeHtml(run.status)}\${run.active?' · activa':''}</option>\`).join('');await loadRun(selected);}catch(error){runSelect.innerHTML='<option value="">Error cargando corridas</option>';runSummary.innerHTML='<div class="summary-item"><strong>!</strong><span>'+escapeHtml(error.message)+'</span></div>';}}
        async function loadRun(runId){if(!runId)return;const response=await fetch('/api/apriori/run-detail?run='+encodeURIComponent(runId));const run=await response.json();if(!response.ok)throw new Error(run.error);displayedRunSettings=run.settings||null;const isActive=runId===activeRunId;activateRunButton.disabled=isActive||run.status!=='completed';activateRunButton.classList.toggle('active',isActive);activateRunButton.textContent=isActive?'Activa para Pedidos':'Activar para Pedidos';const summary=run.summary||{};runSummary.innerHTML=[['Facturas usadas',summary.categorizedInvoices],['Excluidas',summary.excludedInvoices],['Categorías',summary.categoryCount],['Filas normalizadas',summary.normalizedRows],['Reglas elegibles',summary.eligibleRules],['Reglas seleccionadas',summary.selectedRules]].map(([label,value])=>\`<div class="summary-item"><strong>\${value??'—'}</strong><span>\${label}</span></div>\`).join('');const comparison=summary.supportComparison||[];comparisonBody.innerHTML=comparison.length?comparison.map((row)=>\`<tr class="\${row.support===run.settings.selectionSupport?'selected-support':''}"><td><strong>\${row.support}%</strong></td><td>\${row.minimumInvoices}</td><td>\${row.itemsets}</td><td>\${row.rules}</td><td>\${row.eligibleRules}</td><td>\${row.distinctConsequents}</td><td>\${formatPercent(row.medianConfidence)}</td><td>\${row.medianLift==null?'—':Number(row.medianLift).toFixed(2)}</td><td>\${row.strongRules}</td><td><button class="choose-support" data-support="\${row.support}" \${row.support===run.settings.selectionSupport?'disabled':''}>\${row.support===run.settings.selectionSupport?'Seleccionado':'Usar soporte'}</button></td></tr>\`).join(''):'<tr><td colspan="10" class="empty">Esta corrida todavía no tiene indicadores comparativos.</td></tr>';document.querySelectorAll('.choose-support:not(:disabled)').forEach((button)=>button.addEventListener('click',()=>chooseSupport(runId,Number(button.dataset.support))));zipLink.href='/api/apriori/run-zip?run='+encodeURIComponent(runId);zipLink.classList.toggle('hidden',run.status!=='completed');await loadFiles(runId);}
        activateRunButton.addEventListener('click',async()=>{const runId=runSelect.value;if(!runId)return;activateRunButton.disabled=true;activateRunButton.textContent='Activando…';try{const response=await fetch('/api/apriori/activate-run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId})});const body=await response.json();if(!response.ok)throw new Error(body.error);activeRunId=runId;message.className='message ok';message.textContent='Corrida activada para las recomendaciones de Pedidos.';await loadRuns(runId);}catch(error){message.className='message error';message.textContent=error.message;activateRunButton.disabled=false;activateRunButton.textContent='Activar para Pedidos';}});
        deleteRunsButton.addEventListener('click',async()=>{if(!window.confirm('¿Eliminar definitivamente todas las ejecuciones históricas? También se desactivarán las recomendaciones actuales. La configuración de parámetros se conservará.'))return;deleteRunsButton.disabled=true;try{const response=await fetch('/api/apriori/runs',{method:'DELETE'});const body=await response.json();if(!response.ok)throw new Error(body.error);activeRunId=null;displayedRunSettings=null;message.className='message ok';message.textContent='Se eliminaron '+body.deletedRuns+' ejecuciones. Ya podés comenzar desde cero.';await loadRuns();}catch(error){message.className='message error';message.textContent=error.message;}finally{deleteRunsButton.disabled=false;}});
        async function chooseSupport(runId,support){setRunning(true,'Actualizando selección…');message.className='message';message.textContent='Seleccionando reglas con soporte '+support+'%…';try{const values=settings();values.selectionSupport=support;const response=await fetch('/api/apriori/select-support',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId,settings:values})});const body=await response.json();if(!response.ok)throw new Error(body.error||'No se pudo actualizar el soporte.');form.elements.selectionSupport.value=support;message.className='message ok';message.textContent='Soporte '+support+'% aplicado. Se actualizaron las reglas seleccionadas y el ZIP.';await loadRun(runId);}catch(error){message.className='message error';message.textContent=error.message;}finally{setRunning(false);}}
        runSelect.addEventListener('change',()=>loadRun(runSelect.value).catch((error)=>{message.className='message error';message.textContent=error.message;}));
        function fileConfiguration(file){if(!displayedRunSettings||!['reglas_evaluadas.csv','reglas_seleccionadas.csv'].includes(file.name))return'';const number=(value)=>new Intl.NumberFormat('es-AR',{maximumFractionDigits:2}).format(value);return 'Soporte '+number(displayedRunSettings.selectionSupport)+'% · Generación: confianza ≥ '+number(displayedRunSettings.ruleConfidence*100)+'%, lift > '+number(displayedRunSettings.ruleLift)+' · Selección: confianza ≥ '+number(displayedRunSettings.selectionConfidence*100)+'%, lift ≥ '+number(displayedRunSettings.selectionLift);}
        async function loadFiles(runId){try{const query=runId?'?run='+encodeURIComponent(runId):'';const response=await fetch('/api/apriori/files'+query);const body=await response.json();if(!response.ok)throw new Error(body.error);fileCount.textContent=body.files.length+' archivos';filesBody.innerHTML=body.files.length?body.files.map((file)=>{const config=fileConfiguration(file);return \`<tr><td class="path" title="\${escapeHtml(file.id)}"><div class="file-name">\${escapeHtml(file.id)}</div>\${config?'<div class="file-config">'+escapeHtml(config)+'</div>':''}</td><td>\${formatBytes(file.size)}</td><td>\${formatDate(file.modifiedAt)}</td><td><button class="table-action preview-file" data-file="\${escapeHtml(file.id)}">Ver</button><a class="table-action" href="/api/apriori/download?file=\${encodeURIComponent(file.id)}">Descargar</a></td></tr>\`;}).join(''):'<tr><td colspan="4" class="empty">Todavía no hay archivos CSV.</td></tr>';document.querySelectorAll('.preview-file').forEach((button)=>button.addEventListener('click',()=>openPreview(button.dataset.file)));}catch(error){fileCount.textContent='Error';filesBody.innerHTML='<tr><td colspan="4" class="empty">'+escapeHtml(error.message)+'</td></tr>';}}
        async function openPreview(file){previewTitle.textContent=file;previewHead.innerHTML='';previewBody.innerHTML='<tr><td class="empty">Cargando…</td></tr>';previewMeta.textContent='';modal.classList.add('open');modal.setAttribute('aria-hidden','false');try{const response=await fetch('/api/apriori/preview?file='+encodeURIComponent(file));const body=await response.json();if(!response.ok)throw new Error(body.error);previewHead.innerHTML='<tr>'+body.columns.map((column)=>'<th>'+escapeHtml(column)+'</th>').join('')+'</tr>';previewBody.innerHTML=body.rows.map((row)=>'<tr>'+row.map((cell)=>'<td>'+escapeHtml(cell)+'</td>').join('')+'</tr>').join('');previewMeta.textContent='Mostrando '+body.rows.length+' de '+body.totalRows+' filas.';}catch(error){previewBody.innerHTML='<tr><td class="empty">'+escapeHtml(error.message)+'</td></tr>';}}
        function closePreview(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');}document.getElementById('preview-close').addEventListener('click',closePreview);modal.addEventListener('click',(event)=>{if(event.target===modal)closePreview();});loadSettings().finally(()=>loadRuns());
      </script>
    </body>
  </html>`;
}

module.exports = { renderAprioriHomePage };
